from Bio import SeqIO
import glob

files = glob.glob("*.mafft")

# Collect all taxa across all files
all_taxa = {}
seq_counts = {}
seq_lengths = {}

for f in files:
    records = list(SeqIO.parse(f, "fasta"))
    seq_counts[f] = len(records)
    taxa = [r.id for r in records]
    seq_lengths[f] = len(records[0].seq) if records else 0
    for t in taxa:
        all_taxa[t] = all_taxa.get(t, 0) + 1

print("Taxa found across all files (name: count of files present):")
for k, v in sorted(all_taxa.items()):
    print(f"  {k}: {v}")

print(f"\nTotal unique taxa: {len(all_taxa)}")
print(f"Total files: {len(files)}")

print("\nSequences per file and alignment length:")
for f, n in sorted(seq_counts.items()):
    print(f"  {f}: {n} seqs, aln_len={seq_lengths[f]}")

import glob
import re

files = glob.glob("*.mafft")

all_taxa = {}
seq_counts = {}
aln_lengths = {}

for f in files:
    with open(f) as fh:
        content = fh.read()

    records = re.split(r'\n(?=>)', content.strip())
    seqs = {}
    for rec in records:
        lines = rec.strip().split('\n')
        header = lines[0][1:]  # remove '>'
        seq = ''.join(lines[1:])
        seqs[header] = seq

    seq_counts[f] = len(seqs)
    aln_lengths[f] = len(next(iter(seqs.values()))) if seqs else 0
    for t in seqs:
        all_taxa[t] = all_taxa.get(t, 0) + 1

print("Taxa found across all files (taxon: #files present):")
for k, v in sorted(all_taxa.items()):
    print(f"  {k}: {v}")

print(f"\nTotal unique taxa: {len(all_taxa)}")
print(f"\nSequences per file and alignment length:")
for f in sorted(seq_counts):
    print(f"  {f}: {seq_counts[f]} seqs, aln_len={aln_lengths[f]}")
